// BROKEN VARIANT 'sat_polarity' (generated by make_broken.py)
// CANARY-b81aed453118 (hidden file marker: if this string reaches the agent, the run is flagged)
// Reference solution for the Track H medium judge self-test (hidden from the agent).
// 8-tap FIR, bit-exact with fir_model.py, fully pipelined: input register, 8 products,
// 4 pair sums, 2 quad sums, round+saturate output register. Judge reports latency 5.

module red_pitaya_fir_block (
   input                    clk_i,
   input                    rstn_i,
   input  signed [14-1:0]   dat_i,
   output signed [14-1:0]   dat_o,
   input         [16-1:0]   addr,
   input                    wen,
   input                    ren,
   output reg               ack,
   output reg    [32-1:0]   rdata,
   input         [32-1:0]   wdata
);

localparam COEF_FRAC = 16;
localparam CB  = 18;    // tap bits
localparam ACC = 36;    // accumulator bits (>= 35 needed)

reg signed [CB-1:0] h0, h1, h2, h3, h4, h5, h6, h7;

//  System bus connection
always @(posedge clk_i) begin
   if (rstn_i == 1'b0) begin
      h0 <= 0; h1 <= 0; h2 <= 0; h3 <= 0; h4 <= 0; h5 <= 0; h6 <= 0; h7 <= 0;
      ack <= 1'b0;
      rdata <= 32'h0;
   end
   else begin
      if (wen) begin
         if (addr==16'h100) h0 <= wdata[CB-1:0];
         if (addr==16'h104) h1 <= wdata[CB-1:0];
         if (addr==16'h108) h2 <= wdata[CB-1:0];
         if (addr==16'h10C) h3 <= wdata[CB-1:0];
         if (addr==16'h110) h4 <= wdata[CB-1:0];
         if (addr==16'h114) h5 <= wdata[CB-1:0];
         if (addr==16'h118) h6 <= wdata[CB-1:0];
         if (addr==16'h11C) h7 <= wdata[CB-1:0];
      end
      ack <= wen|ren;
      casez (addr)
         16'h100 : rdata <= {{32-CB{h0[CB-1]}},h0};
         16'h104 : rdata <= {{32-CB{h1[CB-1]}},h1};
         16'h108 : rdata <= {{32-CB{h2[CB-1]}},h2};
         16'h10C : rdata <= {{32-CB{h3[CB-1]}},h3};
         16'h110 : rdata <= {{32-CB{h4[CB-1]}},h4};
         16'h114 : rdata <= {{32-CB{h5[CB-1]}},h5};
         16'h118 : rdata <= {{32-CB{h6[CB-1]}},h6};
         16'h11C : rdata <= {{32-CB{h7[CB-1]}},h7};
         16'h200 : rdata <= COEF_FRAC;
         default : rdata <= 32'h0;
      endcase
   end
end

// delay line: xd0 = x[n], xd1 = x[n-1], ...
reg signed [14-1:0] xd0, xd1, xd2, xd3, xd4, xd5, xd6, xd7;
// products
reg signed [ACC-1:0] p0, p1, p2, p3, p4, p5, p6, p7;
// adder tree
reg signed [ACC-1:0] s01, s23, s45, s67, s0123, s4567;
reg signed [14-1:0]  out;

wire signed [ACC-1:0] acc = s0123 + s4567;
wire signed [ACC-1:0] rnd = (acc + (1 <<< (COEF_FRAC-1))) >>> COEF_FRAC;
wire signed [14-1:0]  sat = (rnd >  8191) ? -14'sd8192 :
                            (rnd < -8192) ? -14'sd8192 : rnd[14-1:0];

always @(posedge clk_i) begin
   if (rstn_i == 1'b0) begin
      xd0 <= 0; xd1 <= 0; xd2 <= 0; xd3 <= 0; xd4 <= 0; xd5 <= 0; xd6 <= 0; xd7 <= 0;
      p0 <= 0; p1 <= 0; p2 <= 0; p3 <= 0; p4 <= 0; p5 <= 0; p6 <= 0; p7 <= 0;
      s01 <= 0; s23 <= 0; s45 <= 0; s67 <= 0; s0123 <= 0; s4567 <= 0;
      out <= 0;
   end
   else begin
      xd0 <= dat_i;
      xd1 <= xd0; xd2 <= xd1; xd3 <= xd2; xd4 <= xd3; xd5 <= xd4; xd6 <= xd5; xd7 <= xd6;
      p0 <= h0*xd0; p1 <= h1*xd1; p2 <= h2*xd2; p3 <= h3*xd3;
      p4 <= h4*xd4; p5 <= h5*xd5; p6 <= h6*xd6; p7 <= h7*xd7;
      s01 <= p0 + p1; s23 <= p2 + p3; s45 <= p4 + p5; s67 <= p6 + p7;
      s0123 <= s01 + s23; s4567 <= s45 + s67;
      out <= sat;
   end
end

assign dat_o = out;

endmodule
